        '        latest = str(p.get("latest_version", "v1.0"))\n'
        '        if not is_newer_version(latest, curr_ver):\n'
        '            continue\n'
        '\n'
        '        update_key = f"{pid}_{latest}"\n'
        '        remind_at = notified.get(update_key) if notified.get(update_key) is not None else notified.get(pid)\n'
