        '    loaded_version = (str(getattr(loaded_plugin, "version", "") or "") or None) if loaded_plugin else None\n'
        '    loaded_enabled = bool(getattr(loaded_plugin, "enabled", True)) if loaded_plugin else False\n'
        '    loaded_path = _normalize_plugin_path(getattr(loaded_plugin, "path", None)) if loaded_plugin else ""\n'
