        'from typing import Any, Callable, Optional\n'
        '\n'
        'import requests\n'
        '\n'
        'from .core import (\n'
        '    _iter_matching_legacy_files,\n'
        '    extract_py_plugin_metadata,\n'
        '    is_newer_version,\n'
        '    plugin_label_from_info,\n'
        '    sanitize_segment,\n'
        ')\n'
        'from .hub_api import (\n'
        '    _extract_json_error,\n'
        '    get_funpay_identity,\n'
