        'def clear_release_notes_cache() -> None:\n'
        '    """Clear in-memory cached release metadata."""\n'
        '    with _RELEASE_CACHE_LOCK:\n'
        '        _CACHED_RELEASE["version"] = None\n'
        '        _CACHED_RELEASE["notes"] = None\n'
        '        _CACHED_RELEASE["ts"] = 0.0\n'
        '\n'
        '\n'
        'def fetch_release_notes(force_refresh: bool = False) -> tuple[str | None, str | None]:\n'
        '    now = time.monotonic()\n'
        '    if not force_refresh:\n'
        '        with _RELEASE_CACHE_LOCK:\n'
        '            if _CACHED_RELEASE["version"] is not None and (now - _CACHED_RELEASE["ts"]) < _CACHE_TTL:\n'
        '                return _CACHED_RELEASE["version"], _CACHED_RELEASE["notes"]\n'
        '\n'
        '    try:\n'
        '        with requests.get(f"{API_BASE}/download_client", stream=True, timeout=5, proxies=NO_PROXY) as response:\n'
        '            response.raise_for_status()\n'
        '            prefix = b""\n'
        '            for chunk in response.iter_content(chunk_size=1024):\n'
        '                prefix += chunk\n'
        '                if len(prefix) >= 16384 or b"\\nRELEASE_NOTES = " in prefix and b"\\nDESCRIPTION = " in prefix:\n'
        '                    break\n'
        '            fields = {}\n'
        '            for line in prefix.decode("utf-8", errors="replace").splitlines():\n'
        '                if line.startswith(("VERSION = ", "RELEASE_NOTES = ")):\n'
