        '\n'
        '        try:\n'
        '            with open(data_file, "r", encoding="utf-8") as f:\n'
        '                loaded = json.load(f)\n'
        '            if isinstance(loaded, dict):\n'
        '                return loaded\n'
        '            logger.error("Hub config at %s has non-dict root; backing up", data_file)\n'
        '        except FileNotFoundError:\n'
        '            default_data = {"keys": {}}\n'
        '            try:\n'
        '                atomic_write_json(data_file, default_data)\n'
        '            except OSError:\n'
        '                logger.warning("Could not initialize config at %s", data_file, exc_info=True)\n'
        '            return default_data\n'
        '        except OSError:\n'
        '            logger.exception("Failed reading Hub config at %s", data_file)\n'
        '            raise\n'
        '        except ValueError:\n'
        '            logger.exception("Failed reading Hub config at %s", data_file)\n'
        '\n'
        '        corrupt_backup = f"{data_file}.corrupt.{int(time.time())}"\n'
        '        try:\n'
        '            os.replace(data_file, corrupt_backup)\n'
        '        except OSError:\n'
        '            logger.warning("Failed to isolate corrupt config to %s", corrupt_backup, exc_info=True)\n'
        '        default_data = {"keys": {}}\n'
        '        try:\n'
        '            atomic_write_json(data_file, default_data)\n'
        '        except OSError:\n'
        '            logger.warning("Could not reset corrupt config at %s", data_file, exc_info=True)\n'
        '        return default_data\n'
        '\n'
        '\n'
        'def save_data(data: dict[str, Any]) -> None:\n'
        '    """Persist Hub config atomically, propagating disk errors to callers."""\n'
        '    with DATA_LOCK:\n'
        '        atomic_write_json(PATHS.data_file, data)\n'
        '\n'
        '\n'
        'def update_data(mutator: Callable[[dict[str, Any]], Any]) -> tuple[dict[str, Any], Any]:\n'
        '    """Perform an atomic read-modify-write update under DATA_LOCK."""\n'
        '    with DATA_LOCK:\n'
        '        data = load_data()\n'
        '        result = mutator(data)\n'
        '        save_data(data)\n'
        '        return data, result\n'
        '\n'
        '\n'
        'def save_pending_restart(payload: dict[str, Any]) -> None:\n'
        '    """Persist pending post-restart notification metadata under DATA_LOCK."""\n'
        '    record = dict(payload)\n'
        '    record.setdefault("created_at", time.time())\n'
        '    update_data(lambda d: d.__setitem__("pending_restart", record))\n'
        '\n'
        '\n'
        'def _validate_pending_restart(raw: Any, max_age_seconds: float) -> Optional[dict[str, Any]]:\n'
        '    """Return shallow copy when pending_restart is a valid dict within max_age_seconds."""\n'
        '    if not isinstance(raw, dict):\n'
        '        return None\n'
        '    try:\n'
        '        created_at = float(raw.get("created_at", 0.0))\n'
        '    except (TypeError, ValueError):\n'
        '        return None\n'
        '    if max_age_seconds > 0 and (time.time() - created_at) > max_age_seconds:\n'
        '        return None\n'
        '    return dict(raw)\n'
        '\n'
        '\n'
        'def clear_pending_restart() -> None:\n'
        '    """Remove pending_restart metadata from disk under DATA_LOCK."""\n'
        '    update_data(lambda d: d.pop("pending_restart", None))\n'
        '\n'
        '\n'
        'def peek_pending_restart(max_age_seconds: float) -> Optional[dict[str, Any]]:\n'
        '    """Inspect pending_restart non-destructively, pruning only corrupt or expired markers."""\n'
        '    with DATA_LOCK:\n'
        '        data = load_data()\n'
        '        if "pending_restart" not in data:\n'
        '            return None\n'
        '        valid = _validate_pending_restart(data.get("pending_restart"), max_age_seconds)\n'
        '        if valid is None:\n'
        '            data.pop("pending_restart", None)\n'
        '            save_data(data)\n'
        '            return None\n'
        '        return valid\n'
