        '\n'
        'class StyledButton(InlineKeyboardButton):\n'
        '    """InlineKeyboardButton subclass preserving Telegram Bot API `style` field in JSON payloads."""\n'
        '\n'
        '    def __init__(\n'
        '        self,\n'
        '        text: str,\n'
        '        callback_data: Optional[str] = None,\n'
        '        url: Optional[str] = None,\n'
        '        style: Optional[ButtonStyle] = None,\n'
        '        icon_custom_emoji_id: Optional[str] = None,\n'
        '        **kwargs: Any,\n'
        '    ) -> None:\n'
        '        normalized_style = style if style in VALID_BUTTON_STYLES else None\n'
        '        super().__init__(text=text, callback_data=callback_data, url=url, **kwargs)\n'
        '        self.style: Optional[str] = normalized_style\n'
        '        self.icon_custom_emoji_id = icon_custom_emoji_id\n'
        '\n'
        '    def to_dict(self) -> dict[str, Any]:\n'
        '        payload = super().to_dict()\n'
        '        if self.style:\n'
        '            payload["style"] = self.style\n'
        '        if self.icon_custom_emoji_id:\n'
        '            payload["icon_custom_emoji_id"] = self.icon_custom_emoji_id\n'
        '        return payload\n'
        '\n'
        '\n'
        '@dataclass(frozen=True)\n'
        'class Btn:\n'
