        '\n'
        '    def to_button(self) -> InlineKeyboardButton:\n'
        '        """Materialize a pyTelegramBotAPI InlineKeyboardButton preserving `style` when set."""\n'
        '        cb_data = compact_callback_data(self.callback_data)\n'
        '        if self.style in VALID_BUTTON_STYLES or self.icon:\n'
        '            return StyledButton(\n'
