        '\n'
        'class KeyboardBuilder:\n'
        '    """Fluent inline keyboard builder supporting styled buttons and compact row composition."""\n'
        '\n'
        '    def __init__(self, max_columns: int = 2) -> None:\n'
        '        self._max_columns = max(1, max_columns)\n'
        '        self._rows: list[list[InlineKeyboardButton]] = []\n'
        '\n'
        '    def row(self, *buttons: Btn) -> KeyboardBuilder:\n'
        '        """Append a full row of one or more buttons."""\n'
        '        if buttons:\n'
        '            self._rows.append([b.to_button() for b in buttons])\n'
        '        return self\n'
        '\n'
        '    def add(self, text: str, callback_data: Optional[str] = None, url: Optional[str] = None, style: Optional[ButtonStyle] = None) -> KeyboardBuilder:\n'
        '        """Append a single full-width button row."""\n'
        '        return self.row(Btn(text=text, callback_data=callback_data, url=url, style=style))\n'
        '\n'
        '    def grid(self, buttons: Sequence[Btn], columns: Optional[int] = None) -> KeyboardBuilder:\n'
        '        """Arrange a sequence of buttons cleanly in rows of `columns` width."""\n'
        '        width = max(1, columns or self._max_columns)\n'
        '        for idx in range(0, len(buttons), width):\n'
        '            self.row(*buttons[idx : idx + width])\n'
        '        return self\n'
        '\n'
        '    def extend(self, rows: Iterable[Sequence[Btn]]) -> KeyboardBuilder:\n'
        '        """Append multiple explicit button rows."""\n'
        '        for row_btns in rows:\n'
        '            if row_btns:\n'
        '                self._rows.append([b.to_button() for b in row_btns])\n'
        '        return self\n'
        '\n'
        '    def build(self) -> InlineKeyboardMarkup:\n'
        '        """Build final InlineKeyboardMarkup ready for send/edit."""\n'
        '        markup = InlineKeyboardMarkup()\n'
        '        for row_btns in self._rows:\n'
        '            markup.row(*row_btns)\n'
        '        return markup\n'
        '\n'
        '\n'
        'def has_styled_buttons(markup: Any) -> bool:\n'
        '    """Return True if any button in an InlineKeyboardMarkup carries a Bot API `style` attribute."""\n'
        '    keyboard = getattr(markup, "keyboard", None)\n'
        '    if not keyboard:\n'
        '        return False\n'
        '    return any(bool(getattr(btn, "style", None)) for row in keyboard for btn in row)\n'
        '\n'
