        'def _strip_button_fields(markup: InlineKeyboardMarkup, fields: tuple[str, ...]) -> InlineKeyboardMarkup:\n'
        '    stripped = InlineKeyboardMarkup()\n'
        '    for row in getattr(markup, "keyboard", []) or []:\n'
        '        plain_row = []\n'
        '        for button in row:\n'
        '            cloned = copy.copy(button)\n'
        '            for field in fields:\n'
        '                setattr(cloned, field, None)\n'
        '            plain_row.append(cloned)\n'
        '        if plain_row:\n'
        '            stripped.row(*plain_row)\n'
        '    return stripped\n'
        '\n'
        '\n'
        'def has_custom_button_icons(markup: Any) -> bool:\n'
        '    return any(\n'
        '        bool(getattr(button, "icon_custom_emoji_id", None))\n'
        '        for row in getattr(markup, "keyboard", []) or [] for button in row\n'
        '    )\n'
        '\n'
        '\n'
        'def render_tree_lines(items: Sequence[str], indent: str = " ") -> list[str]:\n'
        '    """Format items as a compact box-drawing hierarchy using ├ and └ connectors."""\n'
        '    if not items:\n'
        '        return []\n'
        '    last_idx = len(items) - 1\n'
        '    return [\n'
        '        f"{indent}{\'└\' if idx == last_idx else \'├\'} {line}"\n'
        '        for idx, line in enumerate(items)\n'
        '    ]\n'
