class _W1bbexHubLoader(importlib.abc.Loader):
    """Execute a bundled source module inside its isolated virtual package."""

    def __init__(self, mod_name: str, source: str, is_pkg: bool) -> None:
        self._mod_name = mod_name
        self._source = source
        self._is_pkg = is_pkg

    def create_module(self, spec):
        return None

    def exec_module(self, module) -> None:
        module.__file__ = _ENTRY_FILE
        if self._is_pkg:
            module.__path__ = []
            module.__package__ = module.__name__
        else:
            module.__package__ = module.__name__.rpartition(".")[0]
        filename = f"{_ENTRY_FILE}::<{_BUNDLE_PKG}.{self._mod_name}>"
        code = compile(self._source, filename, "exec")
        exec(code, module.__dict__)


class _W1bbexHubFinder(importlib.abc.MetaPathFinder):
    """Resolve imports for the virtual _w1bbex_hub_src package tree."""

    _bundle_id = _BUNDLE_PKG

    def find_spec(self, fullname: str, path=None, target=None):
        if fullname == _BUNDLE_PKG:
            mod_key = "__init__"
            is_pkg = True
        elif fullname.startswith(f"{_BUNDLE_PKG}."):
            sub_name = fullname[len(_BUNDLE_PKG) + 1:]
            pkg_key = f"{sub_name}.__init__"
            if pkg_key in _BUNDLE_SOURCES:
                mod_key = pkg_key
                is_pkg = True
            elif sub_name in _BUNDLE_SOURCES:
                mod_key = sub_name
                is_pkg = False
            else:
                return None
        else:
            return None
        source = _BUNDLE_SOURCES.get(mod_key)
        if source is None:
            return None
        loader = _W1bbexHubLoader(mod_key, source, is_pkg)
        return importlib.util.spec_from_loader(fullname, loader, origin=_ENTRY_FILE, is_package=is_pkg)


def _bootstrap_bundle():
    """Reset prior bundled state and load _w1bbex_hub_src.plugin."""
    sys.meta_path[:] = [f for f in sys.meta_path if getattr(f, '_bundle_id', None) != _BUNDLE_PKG]
    prefix = f"{_BUNDLE_PKG}."
    for name in list(sys.modules):
        if name == _BUNDLE_PKG or name.startswith(prefix):
            sys.modules.pop(name, None)
    sys.meta_path.insert(0, _W1bbexHubFinder())
    return importlib.import_module(f"{_BUNDLE_PKG}.plugin")


_entry_mod = _bootstrap_bundle()
custom_init = _entry_mod.custom_init
post_init_cardinal = _entry_mod.post_init_cardinal
init_cardinal = _entry_mod.init_cardinal
BIND_TO_PRE_INIT = _entry_mod.BIND_TO_PRE_INIT
BIND_TO_POST_INIT = _entry_mod.BIND_TO_POST_INIT
BIND_TO_NEW_MESSAGE = _entry_mod.BIND_TO_NEW_MESSAGE
BIND_TO_DELETE = _entry_mod.BIND_TO_DELETE
